t.script:
(function(){
'use strict';
var message=document.getElementById('ux-control-message');var english=(document.documentElement.lang||'').indexOf('en')===0;
function tell(text,error){if(message){message.hidden=false;message.textContent=text;message.className=error?'ux-control-error':'ux-control-success';}}
async function write(model,id,values){var response=await fetch('/web/dataset/call_kw/'+model+'/write',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:model,method:'write',args:[[id],values],kwargs:{}}})});if(!response.ok)throw new Error('request');var data=await response.json();if(data.error||data.result!==true)throw new Error('access');}
document.querySelectorAll('.ux-task-toggle[data-task-id]').forEach(function(button){button.addEventListener('click',async function(){button.disabled=true;button.setAttribute('aria-busy','true');try{await write('project.task',Number(button.dataset.taskId),{state:button.dataset.nextState});location.reload();}catch(e){button.disabled=false;button.removeAttribute('aria-busy');tell(english?'The task could not be updated. Check your permissions or try signing in again.':'No se pudo actualizar la tarea. Revisa tus permisos o vuelve a iniciar sesión.',true);}});});
var budget=document.getElementById('ux-budget-form');if(budget){budget.addEventListener('submit',async function(event){event.preventDefault();if(!budget.reportValidity())return;var value=Number(budget.elements.budget.value);if(!Number.isFinite(value)||value<0)return;var button=budget.querySelector('button[type="submit"]');button.disabled=true;try{await write('project.project',Number(budget.dataset.projectId),{x_ux_budget_set:true,x_ux_cost_budget:value});location.reload();}catch(e){button.disabled=false;tell(english?'The budget could not be saved. Check your permissions or try signing in again.':'No se pudo guardar el presupuesto. Revisa tus permisos o vuelve a iniciar sesión.',true);}});}
})();
